package com.digitalbase.ticketing.model;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;@Entity@Table(name = "client_profiles")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builderpublic class ClientProfile {    @Id    private Long userId;    @OneToOne(fetch = FetchType.LAZY)    @MapsId    @JoinColumn(name = "user_id")    private User user;    @Column(name = "available_balance", precision = 10, scale = 2)    private BigDecimal availableBalance = BigDecimal.ZERO;    @Column(name = "company_name")    private String companyName;    @Column(name = "stripe_customer_id")    private String stripeCustomerId;}